import{mkdir,readFile,readdir,rm,writeFile}from"node:fs/promises";import{join}from"node:path";import{stopDevelopmentSandboxResources}from"#execution/sandbox/bindings/local.js";const PREFIX=`dev-cleanup-intent.`,SUFFIX=`.json`;async function recordCleanupIntent(t,n){let i=join(t,`.eve`),s=join(i,`${PREFIX}${n.runId}${SUFFIX}`);return await mkdir(i,{recursive:!0}),await writeFile(s,`${JSON.stringify(n)}\n`,`utf8`),async()=>await rm(s,{force:!0})}async function reconcileCleanupIntents(e){let r=join(e,`.eve`),s;try{s=await readdir(r)}catch(e){if(e instanceof Error&&`code`in e&&e.code===`ENOENT`)return;throw e}await Promise.all(s.filter(e=>e.startsWith(PREFIX)&&e.endsWith(SUFFIX)).map(async n=>{try{let a=join(r,n),o=JSON.parse(await readFile(a,`utf8`));if(typeof o.runId!=`string`||typeof o.ownerPid!=`number`||!Number.isInteger(o.ownerPid)||o.ownerPid<=0||isProcessAlive(o.ownerPid))return;await stopDevelopmentSandboxResources({appRoot:e,devRunId:o.runId}),await rm(a,{force:!0})}catch{}}))}function isProcessAlive(e){try{return process.kill(e,0),!0}catch(e){return e instanceof Error&&`code`in e&&e.code===`EPERM`}}export{reconcileCleanupIntents,recordCleanupIntent};